import{z as s,x as B,o as l,c as p,q as r,j as o,D as E,d as e,s as A,S as i,b as t}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"领域适配微调","description":"","frontmatter":{"title":"领域适配微调","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/domain-adaptation-ft.md","filePath":"llm/domain-adaptation-ft.md","lastUpdated":1791413859000}'),d={name:"llm/domain-adaptation-ft.md"};function m(F,a,T,h,D,f){const n=B("Mermaid");return l(),p("div",null,[a[2]||(a[2]=r('<h1 id="领域适配微调" tabindex="-1">领域适配微调 <a class="header-anchor" href="#领域适配微调" aria-label="Permalink to &quot;领域适配微调&quot;">​</a></h1><div class="epigraph"><p>先用领域无标注文本把词与语篇分布拉近，再用少量领域指令对齐接口；把说明书直接当 ShareGPT 来 SFT，术语没进先验，格式倒先过拟合。</p><footer>—— Gururangan 等，Don&#39;t Stop Pretraining（EMNLP 2020）；对照指令谱系与 LIMA 的「接口对齐」分工</footer></div><p><a href="/llm/long-context-finetune">长上下文微调</a>处理的是位置与长度。领域适配处理的是<strong>词表与语篇不在预训练里</strong>：生物医学缩写、内部 API、法条结构。Gururangan 等人 2020 年的 Don&#39;t Stop Pretraining 把这条写成两段：领域自适应预训练（DAPT）与任务自适应预训练（TAPT），然后再上任务头。指令时代的缺口是有人用<a href="/llm/instruction-data-lineage">Alpaca 谱系</a>一步代替 DAPT，期望模型从 2 万条「解释一下 ICD 码」里长出医学语言模型。本课把继续预训练与领域 SFT 拆开，不把 SFT 对 RL 的样本效率（<a href="/llm/sft-vs-rl-efficiency">下一课</a>）提前写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>通用基座在领域文本上的困惑度高，是因为 n-gram 与语篇结构 OOD，不是因为不会<a href="/llm/chat-template">chat template</a>。SFT 的<a href="/llm/response-only-loss">仅回复损失</a>只更新回答侧，提示里的术语作为条件出现，但模型没有在领域分布上做过「下一词」的密集练习，生成时仍会退回网页腔、杜撰术语。反过来，只做领域继续预训练不做指令 SFT，模型会续写论文，不会按用户祈使句停止。<span class="marginnote">困惑度可以理解成「模型平均在几个候选里犹豫」：读熟悉的新闻时它猜下一个词大约只需在 10 个候选里挑，读到满是缩写的医学报告可能要在 500 个里挑——数字越大，说明这段文本离它学过的分布越远。</span></p><p>两条目标正交：DAPT 改的是 \\(p_{\\mathrm{domain}}(x)\\)，领域 SFT 改的是 \\(p(\\mathrm{assistant}\\mid \\mathrm{domain\\ prefix})\\)。用后者代替前者，等于用稀疏监督去改语言模型先验，样本效率极差，还容易遗忘通用能力。</p><h3 id="领域数据几乎总是全文目标" tabindex="-1">领域数据几乎总是全文目标 <a class="header-anchor" href="#领域数据几乎总是全文目标" aria-label="Permalink to &quot;领域数据几乎总是全文目标&quot;">​</a></h3><p>DAPT 对领域语料做因果（或掩码）语言建模，<strong>不是</strong>仅回复。这与 SFT 课的掩码契约相反，必须在配方里分成两个阶段，而不是共用一个 <code>train_on_inputs=False</code>。TAPT 更窄：在即将做的任务的无标注文本上再继续预训练（如目标论文集），再 SFT。</p><p><span class="marginnote">Gururangan 等人的实验在 BERT 族与分类任务上；解码器 LLM 的对应物是：领域 corpus 上短学习率的继续预训练，再接指令。主张迁移：先适应分布，再适应接口。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>阶段 A：收集领域无标注文本（手册、论文、清洗后的工单正文），按预训练方式打包，全文损失，学习率低于原预训练、高于激进全参 SFT，epoch 很少，监控通用基准与领域困惑度。可用 <a href="/llm/lora">LoRA</a> 做便宜 DAPT，但术语若要求进嵌入，应考虑解冻 embedding 或全文。<span class="marginnote">这个学习率是个折中：太高会把通用能力冲刷掉（所谓「灾难性遗忘」），太低则几亿 token 都推不动术语。常见做法是取原预训练学习率的十分之一到三分之一，只跑 1-3 个 epoch，并全程盯着通用基准别掉。</span></p><p>阶段 B：少量领域指令，经该基座的<a href="/llm/chat-template">模板</a>渲染，<a href="/llm/response-only-loss">仅回复</a>，\\(\\eta\\) 按<a href="/llm/lora-vs-full-lr">LoRA 对全参</a>选。示范要像真实接口（病历问答、条款抽取），不要把教科书章节伪造成用户问题除非产品就是那样。</p>',12)),(l(),o(i,null,{default:E(()=>[A(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20LR%0A%20%20G%5B%22%E9%80%9A%E7%94%A8%E9%A2%84%E8%AE%AD%E7%BB%83%22%5D%20--%3E%20A%5B%22DAPT%EF%BC%9A%E9%A2%86%E5%9F%9F%E5%85%A8%E6%96%87%20LM%22%5D%0A%20%20A%20--%3E%20B%5B%22%E9%A2%86%E5%9F%9F%E6%8C%87%E4%BB%A4%20SFT%22%5D%0A%20%20B%20--%3E%20P%5B%22%E4%BA%A7%E5%93%81%E6%8E%A5%E5%8F%A3%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,"配比：阶段 B 可混少量通用指令，减少格式遗忘。不要把阶段 A 的论文 PDF 未经清洗塞进对话字段。许可与隐私：领域语料常含 PII，这是数据工程，不是学习率。",-1)),a[4]||(a[4]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=t("p",null,[e("继续预训练把嵌入与注意力重新对准领域共现：缩写展开、公式上下文、引用语类。之后 SFT 只需把已经较低的领域困惑度接到助手完成上，示范可以少——这与 "),t("a",{href:"/llm/lima"},"LIMA"),e("「能力在预训练里」同构，只是「预训练」多了一段领域。跳过 DAPT 时，SFT 梯度既要教格式又要教词，低秩适配器往往只记住示范里出现过的术语，一出表就幻觉。")],-1)),(l(),o(i,null,{default:E(()=>[A(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E4%B8%A4%E9%98%B6%E6%AE%B5%E5%90%84%E6%94%B9%E4%BB%80%E4%B9%88%22%5D%20--%3E%20A%5B%22%E9%98%B6%E6%AE%B5A%20DAPT%EF%BC%9A%E6%94%B9%E9%A2%86%E5%9F%9F%E5%88%86%E5%B8%83%20p_domain%22%5D%0A%20%20A%20--%3E%20A2%5B%22%E6%9C%AF%E8%AF%AD%E4%B8%8E%E8%AF%AD%E7%AF%87%E8%BF%9B%E5%85%A5%E5%85%88%E9%AA%8C%EF%BC%8C%E9%A2%86%E5%9F%9F%E5%9B%B0%E6%83%91%E5%BA%A6%E4%B8%8B%E9%99%8D%22%5D%0A%20%20Q%20--%3E%20B%5B%22%E9%98%B6%E6%AE%B5B%20%E9%A2%86%E5%9F%9FSFT%EF%BC%9A%E6%94%B9%E5%8A%A9%E6%89%8B%E6%9D%A1%E4%BB%B6%E5%88%86%E5%B8%83%22%5D%0A%20%20B%20--%3E%20B2%5B%22%E5%AD%A6%E4%BC%9A%E6%8C%89%E6%8C%87%E4%BB%A4%E5%81%9C%E6%AD%A2%E3%80%81%E6%8C%89%E6%A8%A1%E6%9D%BF%E5%9B%9E%E7%AD%94%22%5D%0A%20%20A2%20--%3E%20OK%5B%22SFT%20%E5%B0%91%E9%87%8F%E7%A4%BA%E8%8C%83%E5%8D%B3%E5%8F%AF%E5%AF%B9%E9%BD%90%22%5D%0A%20%20B2%20--%3E%20OK%0A%20%20SKIP%5B%22%E8%B7%B3%E8%BF%87%20A%20%E7%9B%B4%E6%8E%A5%20SFT%22%5D%20--%3E%20BAD%5B%22%E6%97%A2%E8%A6%81%E6%95%99%E8%AF%8D%E5%8F%88%E8%A6%81%E6%95%99%E6%A0%BC%E5%BC%8F%EF%BC%8C%E6%98%93%E5%B9%BB%E8%A7%89%E4%B8%8E%E9%81%97%E5%BF%98%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p>遗忘：阶段 A 全参会冲刷通用网页特征；LoRA DAPT 忘得少，领域先验也可能学不足。应用 Biderman 等人的「学得少、忘得少」判断：术语密集任务倾向更多参数或解冻底层；通用助手 + 薄领域倾向 LoRA。</p><p><span class="marginnote">检索增强可以代替一部分 DAPT：把领域知识留在索引里。本课不展开 RAG。选择是产品策略：要内化流程与口吻，用适配；要时效条文，用检索。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>领域 SFT 不能修复错误的教师谱系：用通用 ChatGPT 导出的「医学」ShareGPT，会注入自信的错误。领域示范应专家写或专家滤。长上下文领域（法规全书）要叠加<a href="/llm/long-context-finetune">上一课</a>的位置方案，但先有领域先验再拉窗口。</p><p>评测：领域任务 + 通用保持 + 幻觉抽检。只报领域准确率会选出背了指南全文、不会闲聊也不会拒答的检查点。NEFTune 在术语精确匹配任务上要保守。<span class="marginnote">NEFTune 是训练时往输入嵌入里加一点随机噪声的正则技巧，常能让对话输出更自然。但在术语必须逐字精确的任务上（药名、法规编号、代码标识符），噪声可能把「等位基因」教成错别字——所以这类任务要么关掉，要么把噪声幅度调小。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>领域适配先 DAPT（全文 LM）再领域指令 SFT（仅回复），不要用对话表代替分布适应。</li><li>两阶段的损失与学习率契约不同，不可共用一份掩码配置。</li><li>术语要进先验；接口对齐用少量真示范。</li><li>LoRA 减少遗忘也限制内化；嵌入是否解冻单独决策。</li><li>评测保留通用能力与幻觉，不只报领域准确率。</li><li>出处：Gururangan 等，Don&#39;t Stop Pretraining，EMNLP 2020；指令阶段承接 FLAN / Alpaca / ShareGPT 谱系与 LIMA 的接口假说。</li></ul>',7))])}const c=s(d,[["render",m]]);export{P as __pageData,c as default};
